import { useEffect, useState, useRef } from 'react';
import { Link } from 'react-router-dom';
import { motion, useInView } from 'motion/react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { ArrowRight } from 'lucide-react';

interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  description: string;
  featured: boolean;
  imageSlot: string;
}

const categoryColors: Record<string, string> = {
  pottery: 'bg-primary/10 text-primary',
  textiles: 'bg-accent/10 text-accent',
  woodwork: 'bg-secondary/10 text-secondary',
  jewelry: 'bg-muted-foreground/10 text-muted-foreground',
};

function ProductCard({
  product,
  index,
  large = false,
}: {
  product: Product;
  index: number;
  large?: boolean;
}) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: '-60px' });

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 28 }}
      animate={inView ? { opacity: 1, y: 0 } : {}}
      transition={{ duration: 0.5, delay: index * 0.08, ease: 'easeOut' }}
      className={`group relative bg-card rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-shadow duration-300 cursor-pointer ${large ? 'row-span-2' : ''}`}
      style={{ transform: 'translateY(0)' }}
      whileHover={{ y: -4 }}
    >
      <div className={`relative overflow-hidden ${large ? 'aspect-[3/4]' : 'aspect-[4/3]'}`}>
        <img
          src={`/airo-assets/images/${product.imageSlot}`}
          alt={product.name}
          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/30 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
      </div>
      <div className="p-5">
        <span
          className={`inline-block text-xs font-sans font-medium px-2.5 py-1 rounded-full mb-2 capitalize ${categoryColors[product.category] || 'bg-muted text-muted-foreground'}`}
        >
          {product.category}
        </span>
        <h3 className="font-heading text-lg font-semibold text-foreground leading-snug mb-1">
          {product.name}
        </h3>
        <p className="font-sans text-sm text-muted-foreground leading-relaxed mb-3 line-clamp-2">
          {product.description}
        </p>
        <div className="flex items-center justify-between">
          <span className="font-heading text-xl font-bold text-primary">${product.price}</span>
          <span className="font-sans text-xs text-muted-foreground group-hover:text-primary transition-colors flex items-center gap-1">
            View Details <ArrowRight size={12} />
          </span>
        </div>
      </div>
    </motion.div>
  );
}

