/**
 * Products Service
 *
 * Central module for all product-related types and data-fetching logic.
 * Import from here in pages, loaders, and any component that needs product data.
 */

export type ProductCategory = 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

export interface Product {
  id: string;
  name: string;
  category: ProductCategory;
  price: number;
  description: string;
  featured: boolean;
  imageSlot: string;
}

export interface FetchProductsOptions {
  category?: ProductCategory;
  featured?: boolean;
}

/**
 * Fetch products from the API, with optional category and featured filters.
 * Throws a Response (suitable for React Router loaders) on non-OK status.
 */
export async function fetchProducts(options: FetchProductsOptions = {}): Promise<Product[]> {
  const params = new URLSearchParams();
  if (options.category) params.set('category', options.category);
  if (options.featured) params.set('featured', 'true');

  const query = params.toString();
  const url = `/api/products${query ? `?${query}` : ''}`;

  const res = await fetch(url);
  if (!res.ok) throw new Response(null, { status: res.status });

  return res.json() as Promise<Product[]>;
}

/**
 * Fetch only featured products (convenience wrapper).
 */
export async function fetchFeaturedProducts(): Promise<Product[]> {
  return fetchProducts({ featured: true });
}

